using Assets.CoreCollapse.Scripts.Structural;using LWS.TruckSports;using UnityEngine;
namespace LWS.TruckTeaParty {
 [RequireComponent(typeof(Rigidbody),typeof(ServingSupport))]public sealed class ServingVessel:Collapser {
  public SportsEventSession session;public MonoBehaviour events;public Rigidbody body;public Transform shell,spout,liquid;public Collider[] physical;public Rigidbody[] fragments;public LineRenderer stream;public ServingContents contents;public int id;public float capacity=1,initialVolume;public bool pourable;public float breakSpeed=4,maximumHealth=1;public Vector3 spawn;public Quaternion spawnRotation=Quaternion.identity;
  public bool PickupAllowed{get;set;}=true;public bool InteractionEnabled{get;set;}public float Volume{get;private set;}public float SpilledVolume{get;private set;}public bool Broken{get;private set;}public bool Banked{get;private set;}public int LastCarrier{get;private set;}=-1;public ServingArm Holder{get;private set;}public int NativeContacts{get;private set;}public int NativePours{get;private set;}public Collider LastSupport{get;private set;}public float SupportAge{get;private set;}
  struct NativeSupport {public Collider self,other;public Vector3 selfPoint,otherPoint;}
  readonly System.Collections.Generic.Dictionary<(Collider,Collider),NativeSupport> nativeSupports=new System.Collections.Generic.Dictionary<(Collider,Collider),NativeSupport>(16);
  readonly System.Collections.Generic.List<(Collider,Collider)> separatedSupports=new System.Collections.Generic.List<(Collider,Collider)>(16);
  public int NativeSupportPairs=>nativeSupports.Count;
  ConfigurableJoint attachment;Vector3[] fragmentPositions;Quaternion[] fragmentRotations;readonly RaycastHit[] hits=new RaycastHit[32];readonly Vector3[] line=new Vector3[18];IServingEvents Events=>events as IServingEvents;
  public void Prepare(){Drop();if(fragmentPositions==null){fragmentPositions=new Vector3[fragments.Length];fragmentRotations=new Quaternion[fragments.Length];for(int i=0;i<fragments.Length;i++){fragmentPositions[i]=fragments[i].transform.localPosition;fragmentRotations[i]=fragments[i].transform.localRotation;}}for(int i=0;i<fragments.Length;i++){var f=fragments[i];if(!f.isKinematic)f.linearVelocity=f.angularVelocity=Vector3.zero;f.isKinematic=true;f.gameObject.SetActive(false);f.transform.localPosition=fragmentPositions[i];f.transform.localRotation=fragmentRotations[i];}support=GetComponent<Support>();support.ClearSupports();startingHp=maximumHealth;currentHp=startingHp;Volume=Mathf.Clamp(initialVolume,0,capacity);SpilledVolume=0;PickupAllowed=true;InteractionEnabled=false;Broken=Banked=false;LastCarrier=-1;NativeContacts=NativePours=0;LastSupport=null;SupportAge=0;nativeSupports.Clear();shell.gameObject.SetActive(true);foreach(var c in physical)c.enabled=true;body.isKinematic=false;body.detectCollisions=true;body.position=spawn;body.rotation=spawnRotation;transform.SetPositionAndRotation(spawn,spawnRotation);body.linearVelocity=body.angularVelocity=Vector3.zero;if(stream!=null)stream.enabled=false;RefreshLiquid();}
  public bool Attach(ServingArm arm){if(!session.Live||!InteractionEnabled||!PickupAllowed||Broken||Banked||Holder!=null||arm==null)return false;Holder=arm;LastCarrier=arm.truck.slot;attachment=gameObject.AddComponent<ConfigurableJoint>();attachment.connectedBody=arm.grip;attachment.autoConfigureConnectedAnchor=true;attachment.anchor=Vector3.zero;attachment.xMotion=attachment.yMotion=attachment.zMotion=ConfigurableJointMotion.Locked;attachment.angularXMotion=attachment.angularYMotion=attachment.angularZMotion=ConfigurableJointMotion.Locked;attachment.projectionMode=JointProjectionMode.PositionAndRotation;attachment.projectionDistance=.08f;foreach(var own in physical)foreach(var other in arm.contacts)if(own!=null&&other!=null)Physics.IgnoreCollision(own,other,true);return true;}
  public void Drop(){if(Holder!=null){foreach(var own in physical)foreach(var other in Holder.contacts)if(own!=null&&other!=null)Physics.IgnoreCollision(own,other,false);var old=Holder;Holder=null;old.Released(this);}if(attachment!=null){attachment.xMotion=attachment.yMotion=attachment.zMotion=ConfigurableJointMotion.Free;attachment.angularXMotion=attachment.angularYMotion=attachment.angularZMotion=ConfigurableJointMotion.Free;attachment.connectedBody=null;Destroy(attachment);attachment=null;}}
  public float Accept(float amount){if(Broken||Banked||!float.IsFinite(amount)||amount<=0||Vector3.Dot(transform.up,Vector3.up)<.65f)return 0;float accepted=Mathf.Min(amount,capacity-Volume);Volume+=accepted;RefreshLiquid();return accepted;}
  public float Take(float amount){if(Broken||Banked||!float.IsFinite(amount)||amount<=0)return 0;float taken=Mathf.Min(Volume,amount);Volume-=taken;RefreshLiquid();return taken;}
  public void SetPreparedContents(ServingContents kind,float amount){if(Broken||Banked)return;contents=kind;Volume=Mathf.Clamp(amount,0,capacity);RefreshLiquid();}
  public void TickLiquid(float dt){if(stream!=null)stream.enabled=false;if(!session.Live||!InteractionEnabled||Broken||Banked||dt<=0)return;SupportAge+=dt;ValidateNativeSupports();float upright=Vector3.Dot(transform.up,Vector3.up);
   if(pourable&&spout!=null&&Volume>0&&Vector3.Dot(spout.forward,Vector3.down)>.22f){float amount=Mathf.Min(Volume,dt*.65f*Mathf.InverseLerp(.22f,.9f,Vector3.Dot(spout.forward,Vector3.down)));Volume-=amount;float received=CastStream(amount,out Vector3 end);if(received>0)NativePours++;if(amount>received)Spill(amount-received,end);}
   else if(!pourable&&Volume>0&&upright<.8f){float spill=Mathf.Min(Volume,dt*Mathf.Lerp(.05f,.7f,Mathf.InverseLerp(.8f,-.2f,upright)));Volume-=spill;Spill(spill,transform.position);}
   RefreshLiquid();}
  float CastStream(float amount,out Vector3 end){Vector3 p=spout.position;Vector3 velocity=spout.forward*1.5f;line[0]=p;int length=1;end=p;for(int step=0;step<17;step++){velocity+=Physics.gravity*.075f;var next=p+velocity*.075f;var delta=next-p;int count=Physics.SphereCastNonAlloc(p,.055f,delta.normalized,hits,delta.magnitude,~0,QueryTriggerInteraction.Collide);float nearest=float.MaxValue;RaycastHit closest=default;bool hit=false;for(int i=0;i<count;i++){var h=hits[i];if(h.collider.transform.IsChildOf(transform)||Holder!=null&&h.collider.transform.IsChildOf(Holder.truck.transform))continue;if(h.distance<nearest){nearest=h.distance;closest=h;hit=true;}}line[length++]=hit?closest.point:next;if(hit){end=closest.point;DrawStream(length);var receiver=closest.collider.GetComponent<ServingReceiver>();return receiver!=null?Mathf.Clamp(receiver.Receive(this,contents,amount,end),0,amount):0;}p=next;end=p;}DrawStream(length);return 0;}
  void DrawStream(int count){if(stream==null)return;stream.enabled=true;stream.positionCount=count;for(int i=0;i<count;i++)stream.SetPosition(i,line[i]);}
  void Spill(float amount,Vector3 point){if(amount<=0)return;SpilledVolume+=amount;Events?.Spilled(this,amount,point);}
  void RefreshLiquid(){if(liquid==null)return;liquid.gameObject.SetActive(!Broken&&Volume>.005f);liquid.localPosition=Vector3.up*Mathf.Lerp(.15f,1.2f,Mathf.Clamp01(Volume/capacity));}
  void OnCollisionEnter(Collision c){RecordNativeSupport(c);if(session==null||!session.Live||!InteractionEnabled||Broken||Banked||c.contactCount==0)return;NativeContacts++;var native=GetComponent<IServingNativeContact>();if(native!=null&&native.NativeImpact(this,c))return;float speed=Mathf.Abs(Vector3.Dot(c.relativeVelocity,c.GetContact(0).normal));if(speed>breakSpeed)ReceiveDamage((speed-breakSpeed)*.6f);}
  // Native contact pairs remain valid while sleeping. PhysX does not send
  // CollisionStay for sleeping bodies, so callback age cannot mean separation.
  // Stored contact points on BOTH actual colliders prove continuing proximity;
  // Exit, disabled/destroyed colliders or real relative movement retire the pair.
  void RecordNativeSupport(Collision c){if(Broken||Banked||c.collider==null)return;for(int i=0;i<c.contactCount;i++){var p=c.GetContact(i);if(p.normal.y<=.55f||p.thisCollider==null)continue;var self=p.thisCollider;nativeSupports[(self,c.collider)]=new NativeSupport{self=self,other=c.collider,selfPoint=self.transform.InverseTransformPoint(p.point),otherPoint=c.collider.transform.InverseTransformPoint(p.point)};LastSupport=c.collider;SupportAge=0;}}
  void ValidateNativeSupports(){separatedSupports.Clear();Collider supported=null;foreach(var pair in nativeSupports){var p=pair.Value;bool valid=p.self!=null&&p.other!=null&&p.self.enabled&&p.other.enabled&&p.self.gameObject.activeInHierarchy&&p.other.gameObject.activeInHierarchy;if(valid){float tolerance=p.self.contactOffset+p.other.contactOffset+.01f;valid=(p.self.transform.TransformPoint(p.selfPoint)-p.other.transform.TransformPoint(p.otherPoint)).sqrMagnitude<=tolerance*tolerance;}if(valid)supported=p.other;else separatedSupports.Add(pair.Key);}foreach(var key in separatedSupports)nativeSupports.Remove(key);LastSupport=supported;if(supported!=null)SupportAge=0;}
  void OnCollisionStay(Collision c)=>RecordNativeSupport(c);
  void OnCollisionExit(Collision c){separatedSupports.Clear();foreach(var pair in nativeSupports)if(pair.Key.Item2==c.collider)separatedSupports.Add(pair.Key);foreach(var key in separatedSupports)nativeSupports.Remove(key);ValidateNativeSupports();}
  public override void ReceiveDamage(float damage){if(session==null||!session.Live||!InteractionEnabled||Broken||Banked||!float.IsFinite(damage)||damage<=0)return;base.ReceiveDamage(damage);}
  protected override void Collapse(){if(Broken)return;Broken=true;base.Collapse();Drop();Spill(Volume,body.position);Volume=0;shell.gameObject.SetActive(false);foreach(var collider in physical)collider.enabled=false;for(int i=0;i<fragments.Length;i++){var f=fragments[i];f.gameObject.SetActive(true);f.position=transform.TransformPoint(fragmentPositions[i]);f.rotation=transform.rotation*fragmentRotations[i];f.isKinematic=false;f.linearVelocity=body.linearVelocity+Vector3.up*.7f+(f.position-body.position).normalized;f.angularVelocity=new Vector3(i%3-1,.4f,1-i%3); }body.isKinematic=true;RefreshLiquid();Events?.DishBroken(this,body.position);}
  public void MarkBanked(){Banked=true;Drop();if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;body.isKinematic=true;if(stream!=null)stream.enabled=false;}
  public void Freeze(){Drop();if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;body.isKinematic=true;foreach(var f in fragments){if(!f.isKinematic)f.linearVelocity=f.angularVelocity=Vector3.zero;f.isKinematic=true;}if(stream!=null)stream.enabled=false;}
 }
